// [2.6.9] pasangan (tagihan BK, nilai kontrak) yang tampil di aplikasi untuk satu kontrak: baris Register/Master, ringkasan kontrak
//         (Dashboard & Rekap Tagihan — termasuk nilai hasil koreksi), dan jumlah BK seluruh nomor terkait (Monitoring BK / Keuangan)
function pasanganBK269(x) {
  if (!x) return [];
  const g = x.g || null, P = [[N(x.realisasi), N(x.nilai)]];
  if (g) P.push([N(g.realisasi), N(g.nilai)]);
  if (typeof PROG !== 'undefined') {
    const no = new Set([].concat(x.nomor || [x.key], g ? [g.key, g.keyAsli].concat(g.terkait || []) : []).filter(Boolean));
    const bk = (PROG.data || []).filter(e => no.has(e.noKontrak)).reduce((a, e) => a + N(e.nilai), 0);
    if (bk > 0) { P.push([bk, N(x.nilai)]); if (g) P.push([bk, N(g.nilai)]); }
  }
  return P.filter(p => p[1] > 0);
}
function lunas264(x) {   // [2.6.4] tagihan (BK) sudah mencapai nilai kontrak → tidak perlu notifikasi masa berlaku
  // [2.6.9] selesai bila SALAH SATU ukuran tagihan sudah 100% (dulu hanya realisasi baris kontrak; BK progres dipakai bila realisasi 0)
  return pasanganBK269(x).some(([r, n]) => r >= n - Math.max(1000, n * 0.0001));   // toleransi pembulatan: 0,01% (min. Rp 1.000)
}
window.mp264Lunas = lunas264;
window.mp269PersenBK = x => pasanganBK269(x).reduce((m, [r, n]) => Math.max(m, r / n), 0);   // persen BK tertinggi (0–1+)
